export type Category = "religious" | "philosophy" | "children" | "stories" | "novels" | "selfdev" | "trending" | "science" | "truestory" | "history" | "marriage";
export type Lang = "ar" | "fr" | "en" | "es";
type PageProfile = "short" | "medium" | "long" | "epic";

export interface Book {
  id: string;
  title: string;
  author: string;
  category: Category;
  language: Lang;
  cover: string;
  description: string;
  pages: string[];
  pageCount: number;
  duration?: string;
  rating: number;
  illustration?: string;
}

interface Seed {
  title: string;
  author: string;
  category: Category;
  language: Lang;
  description: string;
  duration?: string;
  rating?: number;
  pageProfile?: PageProfile;
  cover?: string;
  illustration?: string;
}

