const trueStoryExtraSeeds: Seed[] = trueStoryExtraRaw.map(([title, author, language]) => {
  const desc: Record<Lang, string> = {
    ar: `سيرة ذاتية وقصة حقيقية مؤثرة بقلم ${author} — تجربة إنسانية لا تُنسى.`,
    en: `An unforgettable memoir and true story by ${author} — a deeply human experience.`,
    fr: `Un récit vrai et un mémoire inoubliable par ${author} — une expérience profondément humaine.`,
    es: `Una memoria inolvidable y una historia real por ${author} — una experiencia profundamente humana.`,
  };
  return {
    title,
    author,
    category: "truestory" as Category,
    language,
    description: desc[language],
    pageProfile: "long" as PageProfile,
  };
});

